python3 -c "
import json

with open('/app/resources/treasury_bulletin_2016_12.json', 'r') as f:
    data = json.load(f)

# Navigate to find OCS data
def find_ocs(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'outer' in k.lower() or 'continental' in k.lower() or 'shelf' in k.lower() or 'OCS' in k:
                print(f'Found: {k}')
            find_ocs(v, path + '.' + str(k) if path else k)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):  # Only check first few
            find_ocs(item, path + '[' + str(i) + ']')

find_ocs(data)
"
